prompt --application/shared_components/plugins/template_component/amc_next_thread
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(237085240283926253)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_THREAD'
,p_display_name=>'Next Thread'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<article class="amc-NThread-entry">',
'  <span class="amc-NThread-avatar" aria-hidden="true">{if ?IMAGE_URL/}<img class="amc-NThread-img" src="#IMAGE_URL#" alt="" width="32" height="32" loading="lazy">{else/}{if ?INITIALS/}#INITIALS#{else/}<span class="fa {case KIND/}{when system/}fa-cog{when status/}fa-flag-o{otherwise/}fa-user-o{endcase/}"></span>{endif/}{endif/}</span>',
'  <div class="amc-NThread-main">',
'    <p class="amc-NThread-head"><span class="amc-NThread-author">#AUTHOR#</span> <span class="amc-NThread-verb">{case KIND/}{when status/}set the status to{when attachment/}attached a file{when system/}{otherwise/}{endcase/}</span> <time class="amc-NThread-time" datetime="#CREATED#">#CREATED#</time>{case IS_INTERNAL/}{when Y/}<span class="amc-NThread-internal"><span class="fa fa-lock" aria-hidden="true"></span>Internal note</span>{when y/}<span class="amc-NThread-internal"><span class="fa fa-lock" aria-hidden="true"></span>Internal note</span>{when yes/}<span class="amc-NThread-internal"><span class="fa fa-lock" aria-hidden="true"></span>Internal note</span>{when YES/}<span class="amc-NThread-internal"><span class="fa fa-lock" aria-hidden="true"></span>Internal note</span>{when Yes/}<span class="amc-NThread-internal"><span class="fa fa-lock" aria-hidden="true"></span>Internal note</span>{otherwise/}{endcase/}</p>',
'    {if ?BODY/}<p class="amc-NThread-body">#BODY#</p>{endif/}',
'    {if ?ATTACHMENT_NAME/}{if ?ATTACHMENT_URL/}<a class="amc-NThread-file" href="#ATTACHMENT_URL#"><span class="fa fa-paperclip" aria-hidden="true"></span><span class="amc-NThread-fileName">#ATTACHMENT_NAME#</span></a>{else/}<span class="amc-NThread-file"><span class="fa fa-paperclip" aria-hidden="true"></span><span class="amc-NThread-fileName">#ATTACHMENT_NAME#</span></span>{endif/}{endif/}',
'  </div>',
'</article>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NThread amc-NThread--#STYLE#" data-layout="#STYLE#" data-show="#SHOW_LATEST#" data-order="#SORT_ORDER#">',
'  <span class="amc-NThread-i18n" hidden data-today="Today" data-yesterday="Yesterday" data-earlier-one="Show 1 earlier update" data-earlier-other="Show %0 earlier updates" data-shown-one="1 earlier update shown" data-shown-other="%0 earlier updates shown" data-new-one="1 new update" data-new-other="%0 new updates" data-mentioned="Mentioned" data-to="To" data-replying-to="Replying to" data-commented="commented" data-replied="replied" data-noted="added an internal note" data-open="Show message" data-updates-one="update" data-updates-other="updates" data-empty="No updates yet. Add the first comment to start the thread."></span>',
'  <ol class="amc-NThread-source">#APEX$ROWS#</ol>',
'</div>'))
,p_report_row_template=>'<li class="amc-NThread-row amc-NThread-row--{case KIND/}{when status/}status{when system/}system{when attachment/}attachment{otherwise/}comment{endcase/} amc-NThread-state--{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}{case IS_INTERNAL/}{when Y/} is-internal{when y/} is-internal{when yes/} is-internal{when YES/} is-internal{when Yes/} is-internal{otherwise/}{endcase/}{case IS_MINE/}{when Y/} is-mine{when y/} is-mine{when yes/} is-mine{when YES/} is-mine{when Yes/} is-mine{otherwise/}{endcase/}" data-id="#ID#" data-parent="#PARENT_ID#" data-created="#CREATED#" data-mentions="#MENTIONS#">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-thread.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-thread.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'One query row per entry. Map ID, Author and Created (required). Return Created as ISO text with TO_CHAR(created_on, ''YYYY-MM-DD"T"HH24:MI:SS''). Kind is comment, status, system or attachment; for status rows return the new status in Body, for example Approved. Parent ID makes a row a reply; replies to replies are shown under the first entry of their thread. Is Internal Y marks a note that the requester cannot see; Is Mine Y marks the current user''s entries. Body is shown as escaped text with its line breaks. The runtime file groups by day, nests replies, folds long threads and keeps relative times current; after posting with a form, refresh the region and new entries are marked and announced.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(497504446422255212)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'chat'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Layout of the thread; the direction is given in brackets as motion, depth, bold or smart. chat [motion]: conversation bubbles for a customer case or a service desk ticket, your entries on the other side, consecutive messages joined, new messages slide in after a refresh. auditTimeline [bold]: a rail with the time beside each entry and status changes in large type with a state marker, for approvals and audit trails. emailThread [smart]: formal correspondence, earlier messages folded to one line with the sender and first words, the latest open, mentions shown as recipients; folds its header in narrow regions. activityFeed [smart]: a compact log of who did what, for a record''s side panel; the time moves into its own column when the region is wide. caseFile [depth]: entries layered as sheets in a case folder, internal notes pinned on top as slips, status changes stamped, attachments as index tabs, for legal, HR and compliance cases.'
);
