,p_is_required=>true
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Unique key of the entry, for example the comment ID. Parent ID of replies refers to it, and it is how new entries are recognised after a region refresh.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(574093364850712597)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_static_id=>'PARENT_ID'
,p_prompt=>'Parent ID'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'ID of the entry this one replies to; empty for a top-level entry. Replies are nested one level under the first entry of their thread, and a reply to a reply says who it answers. A reply whose parent is not in the query is shown as a top-level entry.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(710362646748214551)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
