 p_id=>wwv_flow_imp.id(970583581438563466)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_static_id=>'CREATED'
,p_prompt=>'Created'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>true
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'When the entry was made, as ISO text: TO_CHAR(created_on, ''YYYY-MM-DD"T"HH24:MI:SS''). Return it in the time zone users should see; it is not converted. Entries are sorted by it, grouped by day and shown as a relative time today and a clock time on earlier days.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(925328068843904779)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_static_id=>'BODY'
