,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Text of the entry, shown escaped with its line breaks; HTML is not rendered. For status rows return the new status, for example Approved or On hold, which reads as set the status to Approved. For system rows return the whole sentence, for example First response overdue by 2 hours.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(648990057678133031)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_static_id=>'KIND'
