,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'One of comment, status, system or attachment. Status and system rows are compact events without a bubble; attachment rows read as attached a file. Empty or unknown values are comments.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(346460181991561319)
