,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Optional file name shown as a file chip on any kind of entry, for example Quotation_GPS_2231.pdf.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(896397221970217576)
