,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional download link of the attachment, usually apex_util.get_blob_file_src or apex_page.get_url to a download process. The URL must come from the developer, not from user input.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(691170304461312020)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>12
,p_display_sequence=>120
,p_static_id=>'MENTIONS'
,p_prompt=>'Mentions'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional names mentioned in the entry, separated by a vertical bar, for example Noura Al-Qahtani|Khalid Bin Saeed. Where a name appears in the Body, with or without an at sign, it is highlighted; names that do not appear are listed under the entry. The email style shows them as recipients.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(965478197387240584)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
