,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y for an internal note that the requester cannot see, N or empty otherwise. Internal notes get a dashed edge, a tinted background and the label Internal note in every style.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(760376476132294515)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
