,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y for entries made by the current user, for example case when created_by = :APP_USER then ''Y'' end. Chat puts them on the other side in the theme''s primary tint.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(371475578746908170)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>15
,p_display_sequence=>150
,p_static_id=>'STATE'
,p_prompt=>'State'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'For status and system rows: success, warning, danger, info or neutral, for example success for Approved and danger for Rejected. It colors the status marker, stamp or dot; the status itself is always written in Body. Unknown values render as neutral.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(836068530748721797)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>16
,p_display_sequence=>160
,p_static_id=>'SHOW_LATEST'
,p_prompt=>'Entries Shown'
,p_attribute_type=>'INTEGER'
,p_is_required=>false
,p_default_value=>'6'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Number of latest top-level entries shown when the thread loads, 1 to 200; replies stay with their entry. Earlier entries fold behind a Show earlier updates button that says how many there are. Use 0 to show every entry.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(178296307742351504)
,p_plugin_id=>wwv_flow_imp.id(237085240283926253)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>17
,p_display_sequence=>170
,p_static_id=>'SORT_ORDER'
,p_prompt=>'Order'
