,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'oldestFirst reads like a conversation, with the latest entry at the bottom and the Show earlier updates button at the top. newestFirst puts the latest entry at the top, as in an activity log, and the button at the bottom. Replies are always oldest first under their entry.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(435659008678687278)
,p_plugin_attribute_id=>wwv_flow_imp.id(178296307742351504)
